function slotFx(el,spec){let l=$('#fxl');if(!l){l=document.createElement('div');l.id='fxl';document.body.appendChild(l);}const[m,col,n]=spec.split(':'),b=el.getBoundingClientRect(),x=b.left+b.width/2,y=b.top+b.height/2,R=Math.random;
 for(let i=0;i<(+n||4);i++){const e=document.createElement('i'),a=R()*6.283,d=16+R()*12,dx=m==='r'?Math.cos(a)*d:m==='a'?(R()-.5)*30:(R()-.5)*16,dy=m==='r'?Math.sin(a)*d:m==='u'?-18-R()*14:m==='d'?16+R()*12:-14-R()*10;
  e.className='fxp'+(m==='a'?' a':m==='d'?' d':'');e.style.cssText=`left:${x-2}px;top:${y-2}px;background:${col};--dx:${dx.toFixed(1)}px;--dy:${dy.toFixed(1)}px;animation-delay:${(i*.03).toFixed(2)}s`;e.addEventListener('animationend',()=>e.remove());l.appendChild(e);}}
/* per-charm numbers (v1.73.2): each charm that changed a merge pops what it added under its header slot. Points blue, +Mult pink, ×Mult gold */
function cpop(ct){const t=$('#hd .t'),by={};for(const[i,k,v]of ct)(by[i]=by[i]||[]).push(k==='x'?`<u class="cx">×${num(v)}</u>`:k==='a'?`<u class="ca">+${num(v)}</u>`:`<u class="cp">+${num(v)}</u>`);for(const i in by){const el=t&&t.children[i];if(!el)continue;const o=el.querySelector('.cpop');if(o)o.remove();const b=document.createElement('b');b.className='cpop';b.innerHTML=by[i].join('');el.appendChild(b);setTimeout(()=>b.remove(),RMO?700:950);}}
function rgPulse(ids,ct){if(ct&&ct.length)cpop(ct);if(!RUN||G.chKey==null)return;const t=$('#hd .t'),now=performance.now();for(const id of new Set(ids)){const ci=RUN.ch.findIndex(c=>c.id===id),oi=RUN.or.findIndex(c=>c.id===id),el=ci>=0?t.children[ci]:oi>=0?t.querySelector(`[data-o="${oi}"]`):null;if(!el)continue;const a=ANIM[id]||['hop'],px=el.querySelector('.px');
 el.classList.remove('hit');void el.offsetWidth;el.classList.add('hit');if(px){px.style.animation='none';void px.offsetWidth;px.style.transformOrigin=a[0]==='swing'?'50% 0':'';px.style.animation=`m-${a[0]} .55s ease-out`;}
 if(a[1]&&!(el._ft>now-180)){el._ft=now;slotFx(el,a[1]);}}}
function rgSave(){RUN.pile=G.g?G.g.snap():[];store.set('run',RUN);PF.save();cloudPush();}
const rgSee=(k,ids)=>{if(RUN&&!RUN.dev)PF.see(k,ids);}; /* glossary: the player has now met these */
function rgBar(){const m=RG.score(RUN,0,{l:-1,combo:0,n:0,idle:1,jd:99,dl:99,jm:0,pu:0,tu:0,high:false}).m;return `<p class="tg">Base Mult ×${m.toFixed(1)} · ${cn(RUN.coins)} · Run score ${RUN.total}</p>`;}
function rgTrack(){let h='';for(let j=0;j<3;j++){const c=RG.jarCfg(RUN,j),done=j<RUN.jar;h+=`<div class="nd${done?' done':j===RUN.jar?' cur':''}${c.boss?' boss':''}">${done?ic('check'):c.boss?`<i class="slot boss">${ic(icn(c.boss))}</i>`:`<u>${j+1}</u>`}<b>${c.boss?(j===2?'Boss':'Mini boss'):'Jar '+(j+1)}</b><small>${done?'Done':'Score '+c.quota}</small></div>`;}
 const nx=RG.jarCfg(RUN);return `${rgDm()}<div class="trk">${h}</div><p class="nxt">Next: <b>${nx.boss?BOSS[nx.boss].n:'Jar '+(RUN.jar+1)}</b>. Score <b>${nx.quota}</b> in <b>${nx.drops}</b> drops for ${cn(nx.pay)}</p>${rgCt()}${rgBossP()}`;}
/* the run at a glance (v1.73): one pip per depth with its boss, a tap opens the map */
function rgDm(){const n=RG.nd(RUN),d=RUN.depth,top=Math.max(n,d+1),a=d<=n?1:d-6;let h='';for(let i=a;i<=Math.min(top,a+7);i++)h+=`<i class="dp${i<d?' done':i===d?' cur':''}${BOSS[RG.boss(RUN,i)].fin?' fin':''}">${i<d?ic('check'):ic(icn(RG.boss(RUN,i)))}<small>${i}</small></i>`;return `<button class="dmap" data-a="rmap" aria-label="Map of the run">${h}<span>Map</span></button>`;}
/* the contract on offer for the jar that is up next (hub and shop). Signing it changes the jar (RG.jarCfg), so the Next line above it updates */
const p2T=()=>RUN&&RUN.up.thick?`At ${Math.round(RG.p2at(RUN)*100)}% of the target:`:'At half the target:'; /* when a boss reaches phase 2 (Thick Skin moves it) */
function rgCt(){const c=RUN.ct;if(!c)return '';const d=CT[c.id],[k,n]=d.pay,cr=RUN.jarId==='bare',sb=RUN.up.sign*2,pay=k==='coin'?cn(n+sb):(k==='sd'?`${n} level of the ${fnm(c.sd)} seed`:cr?'a gold crate in place of the wooden one':'a wooden crate')+(sb?' and '+cn(sb):'');
 const pic={short:'hour',high:'sky',thin:'ice'}[c.id]||icn(d.r||d.cu),sg=(lastName||'You').slice(0,16);
 return `<div class="wp${c.on?' on':''}"><div class="wph">Contract</div><div class="wpi">${ic(pic)}</div><div class="wpn">${d.n}</div><p class="wpd">${d.cu?RG.curD(d.cu,c.f):d.d}</p><div class="wpr"><small>Reward</small><b>${pay}</b><small>for clearing the jar</small></div><button class="wps" data-a="rct" aria-label="${c.on?'Tear it up':'Sign it'}"><i>x</i><u>${c.on?`<em>${sg}</em>`:''}</u>${c.on?'':'<small>sign here</small>'}</button>${c.on?'<b class="wpst">Signed</b><small class="wpt">Tap the line to tear it up</small>':''}</div>`;}
const rgTags=()=>Object.keys(RUN.tg).map(id=>`<p class="nxt">Skip reward: <b>${SKR[id].n}</b>. ${SKR[id].d}${SKR[id].u>1?` ${RUN.tg[id]} left.`:''}</p>`).join('');
/* this depth's boss rules in words: the mini boss if there is one still to come, then the boss with its phase 2 */
function rgBossP(){const d=RUN.depth,bid=RG.boss(RUN),mid=RUN.jar<2?RG.mid(RUN):null,[e,o]=RG.curse(RUN,d),fl=RG.has(RUN,'flag'),nd=d+1,nb=RG.boss(RUN,nd),[ne,no]=RG.curse(RUN,nd); /* v1.73: icon tiles, a tap shows the rule (rbx) */
 const bt=(k,id,lb,tg,cl='',dd=d)=>`<button class="bxt${cl}" data-a="rbx" data-k="${k}" data-i="${id}" data-d="${dd}">${tile(k==='b'||k==='m'?id:id,'boss')}<b>${lb.replace(/^The /,'')}</b><small>${tg}</small></button>`,cu=(dd,e,o,x)=>bt('e',e,CUR[e].n,'Curse',' cu',dd)+bt('o',o,CUR[o].n,'Phase 2',' cu2'+(x&&RUN.up.hardy?' off':''),dd);
 return `<div class="bxs"><h5>This depth</h5><div class="bxr">${mid?bt('m',mid,BOSS[mid].n,'Mini boss'):''}${bt('b',bid,BOSS[bid].n,'Boss',' bb')}${fl||!CUR[e]?'':cu(d,e,o,1)}</div>${RUN.tut?'':`<h5>Next: depth ${nd}</h5><div class="bxr nx">${bt('b',nb,BOSS[nb].n,'Boss','',nd)}${cu(nd,ne,no,1)}</div>`}</div>`;}
function bxCard(b){const k=b.dataset.k,id=b.dataset.i,d=+b.dataset.d,f=RG.curse(RUN,d)[2],t=b.querySelector('.tile').outerHTML;let h;
 if(k==='e')h=`<div class="th">${t}<div><b>${CUR[id].n}</b> <small class="chip">From the start</small></div></div><p>${RG.curD(id,f)}</p><p class="tg">A curse on the boss jar of depth ${d}.</p>`;
 else if(k==='o')h=`<div class="th">${t}<div><b>${CUR[id].n}</b> <small class="chip">${RUN.up.hardy?'Hardy stops it':'From phase 2'}</small></div></div><p>${CUR[id].d()}</p><p class="tg">A curse on the boss jar of depth ${d}, once the boss reaches phase 2.</p>`;
 else h=`<div class="th">${t}<div><b>${BOSS[id].n}</b> <small class="chip">${k==='m'?'Mini boss':'Boss'} · depth ${d}</small></div></div><p>${RG.bossD0(RUN,id,d)}</p>${k==='b'?(RG.has(RUN,'flag')?'<p><i>White Flag: it never reaches phase 2.</i></p>':`<p><i>${p2T()}</i> ${RG.bossD0(RUN,id,d,1)}</p>`):''}`;
 tipShow(b,h);}
/* the Rogue intro (v1.44): one tile per mechanic, tap for the card (rmech). t = tile class when it needs one */
const MECH=[{ic:'gold',n:'Points × Mult',d:'A merge scores its points times your <b>Mult</b>. Bigger fruit give more points. Charms push both up, and the right pairs combo.'},
 {ic:'bull',n:'Targets',d:'Hit the jar\'s <b>score target</b> before your <b>drops</b> run out. Run dry, or let the pile sit over the line, and the run is over.'},
 {ic:'king',n:'Bosses',d:'Each depth is 3 jars and the third is a <b>boss</b> with a nasty rule. Halfway to its target it reaches <b>phase 2</b> and gets worse. The shop shows the next boss early, so you can prepare.'},
 {ic:'blight',n:'Curses',d:'Every boss brings two <b>curses</b>: one on your drops from the start (orange), one on your Orchard at phase 2 (red). Tap the boss or its curse icons at the top left to read them.'},
 {ic:'hoard',n:'The pile',d:'The pile <b>carries over</b> from jar to jar. It is emptied at each new depth.'},
 {ic:'wallet',n:'Coins and shop',d:'Cleared jars pay coins, and unused drops pay a little more. Spend them in the shop on <b>charms</b> (hold up to '+SLOTS+'), tools, upgrades and seeds. Saved coins earn <b>interest</b>.'},
 {ic:'shake',n:'Tools',d:'<b>Tools</b> sit under the jar. Tap one to use it. They <b>charge as you merge</b>, so use them often. Some switch on and off and use 1 charge every drop while on, some last a few drops.'},
 {ic:'crate_gold',n:'Crates',d:'Every boss drops a <b>crate</b>: pick 1 thing from it, free. The shop sells crates too. A crate offers a <b>fusion</b> first when you hold both halves of one.'},
 {ic:'road',n:'Skipping',d:'Jar 1 or 2 of a depth can be <b>skipped</b>: no pay and no shop, but you pick a wooden crate or another reward. The Map shows what each skip gives.'},
 {ic:'graft',n:'Fusions',d:'Two items that belong together can <b>fuse</b> into one stronger item, which frees a slot. Hold one half and the other turns up more often. Fusions you have made stay in the Almanac.'},
 {ic:'coupon',n:'Contracts',d:'From depth 2, plain jars offer a <b>contract</b>: a rule that makes the jar harder. Sign it and clearing the jar pays extra.'},
 {ic:'citrus',n:'Orchard',d:'The <b>Orchard</b>, the green slots at the top right, holds items that change <b>what drops</b>: more Lemons, a gold fruit now and then, a look at the fruit after Next.'},
 {ic:'zest',n:'Families',d:'Every fruit has a <b>family</b> (Stone fruit, Berries, Citrus, Pome, Tropical, Melons). Some charms score family merges: two Lemons merging is a Citrus merge. The Almanac\'s Fruit tab lists them.'},
 {ic:'juicer',t:'r0 ed-j',n:'Editions',d:'Some items come <b>Candied</b> (sugar glaze, +10 points on every merge), <b>Juiced</b> (rainbow shimmer, +1.5 Mult) or, very rarely, <b>Ambrosia</b> (golden glow, ×1.5 Mult). They cost a little more and sell for more.'},
 {ic:'cat',n:'Pet levels',d:'Pets <b>level up</b>, from 1 to 5, as you clear jars and as they work. Each level makes them act more often, eat bigger fruit and score more. Each pet also has a <b>skill tree</b>: every level after the first gives an ability point to spend between jars, on three branches. Tap the pet in the header for its tree. Its look follows the branch you build.'},
 {ic:'joker',n:'Wildcards',d:'A <b>Wildcard</b> has a rainbow ring. It merges with a fruit of any size and makes one size up from the bigger of the two, for half the points.'},
 {ic:'i',n:'Info button',d:'The <b>i</b> button under the jar pauses and opens Run info (with a score table), the Almanac and Options.'}];
function rgIntro(){if(G.state!=='menu'||RUN)menu();G.mode='rogue';store.set('mode','rogue');setBest();const sv=RG.saved(),ok=!!sv;
 const m=show(`<h3>Rogue run</h3>${ok?`<button class="go rogue" data-a="rcont">Continue (depth ${sv.depth}, jar ${sv.jar+1})</button><br>`:''}${tuN()?`<div class="tutc">${tile('pet','r1')}<div><b>New to Rogue?</b><span>A guided run: 3 short jars, about 5 minutes.</span></div><button class="go rogue sm" data-a="rtut">Play</button><button class="lnk" data-a="rtno">No thanks</button></div>`:''}<button class="go${ok||tuN()?' alt':' rogue'}" data-a="rnew">New run</button><p class="tg">Go ${DEPTHS} depths down, 3 jars each. Tap a tile to learn how it works.</p><div class="mech">${MECH.map((m,i)=>`<button data-a="rmech" data-i="${i}">${m.t?tile(m.ic,m.t):`<i class="tile r0">${m.ic==='i'?'<b class="mi">i</b>':ic(icn(m.ic))}</i>`}<small>${m.n}</small></button>`).join('')}</div>
<canvas id="chain"></canvas><p style="font-size:15px;color:var(--muted);margin:0">Fruit sizes, as charms and bosses call them.</p>
<button class="go alt sm" data-a="almanac" data-f="intro">Almanac</button><button class="go alt sm" data-a="menu">Back</button>${tuN()?'':'<br><button class="go lnk" data-a="rtut">Replay the tutorial</button>'}`);chain(m,1);}
const tuN=()=>{const S=(PF.d||PF.load()).stats;return !S.tut&&!S.runs;}; /* the tutorial callout: never played it, never started a run */
/* new run: pick a starting jar and a stake */
/* New run (v1.54): three tabs (G.suT): Your run (a 4-column jar grid since v1.55.4, the picked jar's panel, a Ripeness stepper, Start run fixed at the bottom), Daily run (dlyTab) and Profile (profH, signed in). A locked jar is a dark shape; tapping it opens a card with the award (rjlk). pips(best) = 8 squares in the Ripeness colours, filled up to the best Ripeness won */
const pips=b=>`<span class="pips">${RPC.map((c,i)=>`<i${i<(b||0)?` style="background:${c}"`:''}></i>`).join('')}</span>`,rpPill=k=>`<b class="rpp" style="background:${RPC[k-1]}${k>=6?';color:#fff2d8':''}">Ripeness ${k}</b>`;
function rgSetup(){const U=G.su=G.su||{jar:store.get('jar','classic'),stake:store.get('stake',1)};if(!JARS[U.jar]||PF.lk('jar.'+U.jar))U.jar='classic';const mx=RG.stakeMax(U.jar);U.stake=clampN(+U.stake||1,1,mx);const T=G.suT=G.suT||'run',old=ui.querySelector('.msg'),sy=old&&old.querySelector('.sut')&&old.dataset.t===T?old.scrollTop:0;G.pfIn=T==='pf'?1:0;
 const tabs=`<div class="tabs sut">${[['run','Your run'],['dly','Daily run'],['pf','Profile']].map(([t,n])=>`<button data-a="rsut" data-t="${t}" class="${t===T?'on':''}${t==='dly'?' dt':''}">${n}</button>`).join('')}</div>`;let body,foot;
 if(T==='dly'){body=dlyTab();foot=`${dlyBtn()}<button class="go alt" data-a="rogue">Back</button>`;}
 else if(T==='pf'){body=AU&&AU.name&&LB?profH():`<p>Sign in to get a profile: three stats of your choice that other players see, and a friends list with its own leaderboards.</p>${LB?'<button class="go" data-a="acc" data-m="in">Sign in</button>':''}`;foot='<button class="go alt" data-a="rogue">Back</button>';}
 else{const best=PF.d.stakes[U.jar]||0,grid=Object.keys(JARS).map(id=>{const lk=PF.lk('jar.'+id),on=id===U.jar;return `<button class="jt${on?' on':''}${lk?' lk':''}" data-a="${lk?'rjlk':'rjar'}" data-j="${id}">${tile('jar_'+id,on?'r1':'')}<small>${lk?'Locked':JARS[id].n.replace(/ Jar$/,'')}</small>${lk?'':pips(PF.d.stakes[id])}</button>`;}).join('');
  body=`<div class="jg">${grid}</div><div class="jp">${tile('jar_'+U.jar,'big r1')}<div><b>${JARS[U.jar].n}</b><p>${JARS[U.jar].d}</p>${pips(best)}<small>${best?'Best won: Ripeness '+best:'Not won yet'}</small></div></div>
<div class="rps"><button data-a="rstake" data-s="${U.stake-1}"${U.stake<=1?' disabled':''} aria-label="Lower">◀</button>${rpPill(U.stake)}<button data-a="rstake" data-s="${U.stake+1}"${U.stake>=mx?' disabled':''} aria-label="Higher">▶</button></div>
<p class="rpa">${U.stake>1?'Adds: <b>'+STAKES[U.stake-1]+'</b>':STAKES[0]}</p>${mx<STAKES.length&&U.stake===mx?`<p class="tg">Win on Ripeness ${mx} with ${JARS[U.jar].n} to open Ripeness ${mx+1}.</p>`:''}
${U.stake>2?`<details class="dd rpl"><summary>All ${U.stake-1} rules at Ripeness ${U.stake}</summary><ul class="wl">${STAKES.slice(1,U.stake).map((t,i)=>`<li><span>${i+2}</span><div>${t}</div></li>`).join('')}</ul></details>`:''}`;
  foot=`<button class="go rogue" data-a="rbegin">Start: ${JARS[U.jar].n.replace(/ Jar$/,'')} · Ripeness ${U.stake}</button><button class="go alt" data-a="rogue">Back</button>`;}
 const m=show(`<h3>New run</h3>${tabs}<div class="sub">${body}</div><div class="sfoot">${foot}</div>`);m.classList.add('sux');m.dataset.t=T;m.scrollTop=sy;if(T==='pf')profBind(m);if(T==='dly')dlyPrev(m);}
/* the Daily run tab: today's jar and Ripeness, the countdown, the top 3 and your place (dlyPrev fills them) */
function dlyTab(){const d=dayN(),j=dlyJ(d),k=dlyK(d);return `<div class="dlt"><p class="dld">${dlyDate(d)} · new run in ${dlyLeft()}</p><div class="jp">${tile('jar_'+j,'big r1')}<div><b>${JARS[j].n}</b><p>${JARS[j].d}</p>${rpPill(k)}</div></div><p>The same run for everyone today: same bosses, shops, crates and fruit order, with every item open. A short run: 4 depths, and every jar pays double. One attempt, with its own board.</p>${LB?'<div class="sec"><h5>Today\'s top 3</h5><div id="dtp"><p class="none">Loading…</p></div><button class="go alt sm" data-a="dlyb">Full board</button></div>':''}</div>`;}
function dlyBtn(){const d=dayN(),sv=RG.saved();return sv&&sv.dly===d?'<button class="go dly" data-a="rcont">Continue today\'s run</button>':dlyDone(d)?'<p class="tg">Played today. Come back tomorrow.</p>':'<button class="go dly" data-a="rdaily">Play today\'s run</button>';}
