 const fx=G.crA!==C&&!matchMedia('(prefers-reduced-motion:reduce)').matches,cue=()=>rareCue(C.opts.filter(o=>o.k==='ch').map(o=>o.id));G.crA=C;if(!fx)cue();for(const o of C.opts){if(o.k==='fu'){rgSee('fu',o.id);rgSee(CH[o.id]?'ch':'tl',o.id);}else if(o.k!=='coin')rgSee(o.k==='or'?'ch':o.k,o.id);}rgSave();
