  if(o.k==='sd')return `<li>${tile('fr'+o.id,'sd')}<div><b>${fnm(o.id)} Seed</b> <small class="chip">+${o.n} level${o.n>1?'s':''}</small><br>${o.n>1?'Each level: ':''}${sdD(o.id)}</div>${btn}</li>`;
